        if (immune != null) {
            for (char ic : immune) {
                if (ic == c) {
                    return String.valueOf(c);
                }
            }
        }

        // If the character is in the set of unencoded characters, return it unchanged
        if (UNENCODED_SET.contains(c)) {
            return String.valueOf(c);
        }

        // Convert the character to its UTF‑8 byte sequence
        byte[] bytes = toUtf8Bytes(String.valueOf(c));
        StringBuilder sb = new StringBuilder(bytes.length * 3);

        // Percent‑encode each byte
        for (byte b : bytes) {
