import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * A thread‑safe, XXE‑protected Atom provider.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared, immutable Abdera engine instance. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Flag controlling charset autodetection. */
    private boolean autodetectCharset;

    /* --------------------------------------------------------------------- */
    /* MessageBodyReader implementation                                       */
    /* --------------------------------------------------------------------- */

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a parser instance from the shared engine.
        Parser parser = ATOM_ENGINE.getParser();

        // Create a fresh, thread‑local ParserOptions instance.
        ParserOptions baseOptions = parser.getDefaultParserOptions();
        ParserOptions options = (baseOptions != null) ? baseOptions.clone() : new ParserOptionsImpl();

        // Disable entity resolution to mitigate XXE attacks.
        options.setResolveEntities(false);

        // Apply charset autodetection setting if required.
        options.setAutodetectCharset(autodetectCharset);

        // Parse the input stream using the secured options.
        Document<T> document = parser.parse(entityStream, options);

        // Return the root element of the parsed Atom document.
        return document.getRoot();
    }

    /* --------------------------------------------------------------------- */
    /* Other methods omitted for brevity                                      */
    /* --------------------------------------------------------------------- */

    /* --------------------------------------------------------------------- */
    /* Helper: minimal ParserOptions implementation for fallback           */
    /* --------------------------------------------------------------------- */
    /**
     * Lightweight fallback implementation of {@link ParserOptions} used when
     * {@code getDefaultParserOptions()} returns {@code null}. This class
     * implements only the methods required by the provider.
     */
    private static final class ParserOptionsImpl implements ParserOptions {
        private boolean resolveEntities = true;
        private boolean autodetectCharset = false;

        @Override
        public void setResolveEntities(boolean resolve) {
            this.resolveEntities = resolve;
        }

        @Override
        public boolean getResolveEntities() {
            return resolveEntities;
        }

        @Override
        public void setAutodetectCharset(boolean autodetect) {
            this.autodetectCharset = autodetect;
        }

        @Override
        public boolean getAutodetectCharset() {
            return autodetectCharset;
        }

        @Override
        public ParserOptions clone() {
            ParserOptionsImpl clone = new ParserOptionsImpl();
            clone.resolveEntities = this.resolveEntities;
            clone.autodetectCharset = this.autodetectCharset;
            return clone;
        }

        /* The remaining methods of ParserOptions are no‑ops for this
         * lightweight implementation. They are left unimplemented because
         * they are not required by the current usage pattern. */
    }
}
