public static File allocateFile(File dir, String name) {
    if (dir == null || name == null) throw new IllegalArgumentException("dir and name must not be null");
    // strip query
    int q = name.indexOf('?');
    if (q > 0) name = name.substring(0, q);
    // Reject absolute paths or containing separators
    if (name.contains("/") || name.contains("\\") || name.startsWith(".") || name.contains("..")) {
        // sanitize by removing path separators and '..'
        name = name.replaceAll("[/\\\\]+", "_");
        name = name.replaceAll("\\.\\.+", "");
    }
    // Resolve path
    Path dirPath = dir.toPath().toAbsolutePath().normalize();
    Path targetPath = dirPath.resolve(name).normalize();
    if (!targetPath.startsWith(dirPath)) {
        throw new SecurityException("Attempt to escape target directory");
    }
    File file = targetPath.toFile();
    // uniqueness
    String fileName = file.getName();
    int dot = fileName.lastIndexOf('.');
    String prefix = dot < 0 ? fileName : fileName.substring(0, dot);
    String suffix = dot < 0 ? "" : fileName.substring(dot);
    int index = 2;
    while (file.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        file = dirPath.resolve(newName).toFile();
    }
    file.getParentFile().mkdirs();
    return file;
}

