    /* Whitelist of supported algorithms.  Only these algorithms are allowed   */
    /* for signature verification.  This prevents the use of insecure or     */
    /* unsupported algorithms such as "none".                                 */
    /* --------------------------------------------------------------------- */
    private static final Set<String> ALLOWED_ALGORITHMS =
