                ? header.algorithm.getName()
                : null;

        if (algName == null || algName.trim().isEmpty()) {
            throw new InvalidJWTSignatureException("Missing algorithm in JWT header");
        }

        // Reject unsigned tokens (algorithm "none") and any algorithm not in the whitelist
        if ("none".equalsIgnoreCase(algName)) {
            throw new InvalidJWTSignatureException("Unsigned JWTs are not allowed");
        }
        if (!ALLOWED_ALGORITHMS.contains(algName)) {
            throw new InvalidJWTSignatureException("Unsupported JWT algorithm: " + algName);
        }

        // The message comprises the first two segments of the entire JWT,
        // the signature is the last segment.
        int index = encodedJWT.lastIndexOf(".");
        if (index <= 0) {
            throw new InvalidJWTSignatureException("Malformed JWT: missing header or payload");
        }
