     * @param entryDate         the modification time of the entry
     * @param isDirectory       whether the entry represents a directory
     * @param mode              the POSIX permission mode (may be {@code null})
     * @param symlinkDestination the target of a symbolic link (may be {@code null})
     * @throws IOException      if an I/O error occurs
     * @throws ArchiverException if the entry cannot be extracted
     */
    protected void extractFile(final File srcF,
                               final File dir,
                               final InputStream compressedInputStream,
                               final String entryName,
                               final Date entryDate,
                               final boolean isDirectory,
                               final Integer mode,
                               String symlinkDestination) throws IOException, ArchiverException {

        if (entryName == null || entryName.trim().isEmpty()) {
            throw new IllegalArgumentException("Entry name must not be null or empty");
        }

        // Resolve the target file and perform Zip‑Slip protection
        final File resolved = new File(dir, entryName);
        final File canonicalDir = dir.getCanonicalFile();
        final File canonicalResolved = resolved.getCanonicalFile();

        // Ensure the resolved path is within the target directory
        String canonicalDirPath = canonicalDir.getPath();
        String canonicalResolvedPath = canonicalResolved.getPath();
        if (!canonicalResolvedPath.startsWith(canonicalDirPath + File.separator)) {
            throw new SecurityException(
                "Entry '" + entryName + "' is outside the target directory");
        }

        final File f = canonicalResolved;

        try {
            // Skip extraction if the file already exists and is newer
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Ensure parent directories exist
            final File dirF = f.getParentFile();
            if (dirF != null) {
                dirF.mkdirs();
            }

            if (!StringUtils.isEmpty(symlinkDestination)) {
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
