     * @param writer        writes the entry data to an {@link OutputStream}
     * @param targetDirectory the directory into which entries are extracted
     * @throws IOException if extraction fails or a security violation is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical target directory once
        Path targetPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String rawName = nextEntry.getName();

            // Basic sanity checks
            if (rawName == null || rawName.isEmpty()) {
                throw new IOException("archive entry has an empty name");
            }

            // Normalise path separators to '/' for consistent handling
            String normalizedName = rawName.replace('\\', '/');

            // Reject absolute paths
