                throw new IOException("absolute entry name not allowed: " + rawName);
            }

            // Reject path‑traversal components
            if (normalizedName.contains("..")) {
                throw new IOException("path traversal detected in entry name: " + rawName);
            }

            // Resolve the entry against the target directory and normalise
            Path entryPath = targetPath.resolve(normalizedName).normalize();

            // Final check: the resolved path must still be within the target directory
            if (!entryPath.startsWith(targetPath)) {
                throw new IOException(
                        "expanding " + rawName + " would create file outside of "
                                + targetDirectory);
