import javax.xml.XMLConstants;
import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.transform.sax.SAXSource;
import javax.xml.transform.stream.StreamSource;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;
import org.apache.camel.Converter;
import org.apache.camel.Exchange;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    /* --------------------------------------------------------------------- */
    /*  Converter Methods                                                    */
    /* --------------------------------------------------------------------- */

    /**
     * Converts a {@link StreamSource} into a {@link SAXSource} while
     * protecting against XML External Entity (XXE) attacks.
     *
     * <p>The method explicitly disables all forms of external entity
     * processing and DTD loading. It also enables the standard
     * {@code FEATURE_SECURE_PROCESSING} flag. If the caller supplies an
     * {@link Exchange} that already contains a {@link SAXParserFactory},
     * the factory is reused but its security features are still enforced.
     *
     * @param source   the source XML stream
     * @param exchange optional Camel exchange that may contain a pre‑configured
     *                 {@link SAXParserFactory}
     * @return a secure {@link SAXSource}
     * @throws SAXException if the XML reader cannot be created
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        if (source == null) {
            throw new IllegalArgumentException("source cannot be null");
        }

        // Build the InputSource from the StreamSource
        InputSource inputSource;
        try {
            if (source.getReader() != null) {
                inputSource = new InputSource(source.getReader());
            } else if (source.getInputStream() != null) {
                inputSource = new InputSource(source.getInputStream());
            } else {
                throw new IllegalArgumentException(
                        "StreamSource must provide either a Reader or an InputStream");
            }
        } catch (Exception e) {
            throw new SAXException("Failed to create InputSource", e);
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        SAXParserFactory sfactory = null;
        XMLReader xmlReader = null;

        try {
            // Reuse factory from exchange if present
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            /* ------------------------------------------------------------------ */
            /*  Configure factory for secure parsing                               */
            /* ------------------------------------------------------------------ */
            enableFeature(sfactory, XMLConstants.FEATURE_SECURE_PROCESSING, true);
            enableFeature(sfactory, "http://xml.org/sax/features/external-general-entities", false);
            enableFeature(sfactory, "http://xml.org/sax/features/external-parameter-entities", false);
            enableFeature(sfactory, "http://apache.org/xml/features/disallow-doctype-decl", true);
            enableFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            enableFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

            sfactory.setNamespaceAware(true);

            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            /* ------------------------------------------------------------------ */
            /*  Apply the same security settings to the XMLReader                 */
            /* ------------------------------------------------------------------ */
            enableFeature(xmlReader, "http://xml.org/sax/features/external-general-entities", false);
            enableFeature(xmlReader, "http://xml.org/sax/features/external-parameter-entities", false);
            enableFeature(xmlReader, "http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (Exception ex) {
            LOG.warn("Cannot create the SAXParser XMLReader, due to {}", ex);
            throw new SAXException("Failed to create XMLReader", ex);
        }

        return new SAXSource(xmlReader, inputSource);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper Methods                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Safely sets a feature on a {@link SAXParserFactory} or {@link XMLReader}.
     * Any failure to set the feature is logged as a warning.
     *
     * @param target the object on which to set the feature
     * @param feature the feature URI
     * @param value the desired boolean value
     */
    private void enableFeature(Object target, String feature, boolean value) {
        try {
            if (target instanceof SAXParserFactory) {
                ((SAXParserFactory) target).setFeature(feature, value);
            } else if (target instanceof XMLReader) {
                ((XMLReader) target).setFeature(feature, value);
            }
        } catch (Exception e) {
            LOG.warn("Feature {} could not be set to {}: {}", feature, value, e.toString());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Other methods (omitted)                                              */
    /* --------------------------------------------------------------------- */
}
